// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
	var j = $(q); if (j.length) return j;
	var P = 'mf_', t = q.trim(), r = t.slice(1);
	if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
	return $(t.slice(0, 1) + r);
};
scwin.trigger2_onclick = function(e) {
	dataList1.insertRow(28);
};
scwin.__isAddedRow = function() {
	var tr = ((j) => j.length ? j : $('#mf_gridView1_body_tbody tr'))($('#gridView1_body_tbody tr')).not("tr.w2grid_hidedRow");
	var el = tr.get(tr.length - 1);
	return scwin.__getJq(el).find("td:first").text() == "31";
}
scwin.__showErrLog = function() {
	var err = WebSquare.logger.getErrorLog();
	return err ? true : false;
}

